export const ROLE_LABELS = {
  tank: 'Tank',
  dps: 'DPS',
  support: 'Support',
}

export const STYLE_LABELS = {
  dive: 'dive',
  brawl: 'brawl',
  poke: 'poke',
  rush: 'rush',
}

export function getHero(slug) {
  return HEROES.find((entry) => entry.slug === slug) ?? null
}

export function getMap(slug) {
  return MAPS.find((entry) => entry.slug === slug) ?? MAPS[0]
}

export function normalizeHeroSlug(value = '') {
  const normalized = String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')

  const aliases = {
    'd-va': 'dva',
    'd-mon': 'dmon',
    lucio: 'lucio',
    'soldier-76': 'soldier-76',
    'torbjorn': 'torbjorn',
  }

  const slug = aliases[normalized] ?? normalized
  return getHero(slug)?.slug ?? ''
}

function hero(slug, name, role, ...styles) {
  return { slug, name, role, styles, portrait: `./assets/heroes/${slug}.png` }
}

function map(slug, name, mode, ...styles) {
  return { slug, name, mode, styles }
}
